head.script:
///////// 1. 변수 및 선언 영역 /////////
scwin.screenId = "jldfil25501";

// TODO Stage2: 컨텍스트 키 출처 미확인(as-is EL · 회신 A-3) — eduCompltAddList

///////// 2. 초기화 영역 /////////
/**
 * @method
 * @name onpageload
 * @description 화면 로딩 시 초기 처리 — init 순차 호출
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.onpageload = async function () {
    try {
        scwin.init_recvParam();
        scwin.init_fillGen();
        scwin.init_conds();
        await scwin.init_loadList();
    } catch (e) {
        await $c.exception.handleError(e, { context: 'jldfil25501.onpageload' });
    }
};

/**
 * @method
 * @name init_conds
 * @description 표시 조건 평가 — 컨텍스트·세션 값에 따라 영역·버튼을 show/hide(진입 1회·데이터 재적재 시 재호출)
 * @returns {void}
 * @hidden N
 */
scwin.init_conds = function () {
    const binds = [{ id: "c_when_74", fn: function(){ return (!(String(((dma_pageContext.get("eduCompltAddList") ?? "")) === null ? '' : ((dma_pageContext.get("eduCompltAddList") ?? ""))).length === 0)); } }, { id: "c_otherwise_80", fn: function(){ return (!((!(String(((dma_pageContext.get("eduCompltAddList") ?? "")) === null ? '' : ((dma_pageContext.get("eduCompltAddList") ?? ""))).length === 0)))); } }];
    binds.forEach(function (b) {
        const comp = $c.util.getComponent(b.id);
        if (!comp) { return; }
        const ok = !!b.fn();
        if (ok) { comp.show(); } else { comp.hide(); }
        if (ok && b.grids) {
            b.grids.forEach(function (gid) {
                const gc = $c.util.getComponent(gid);
                if (gc && gc.refreshGridView) { gc.refreshGridView(); }
            });
        }
    });
};

/**
 * @method
 * @name init_fillGen
 * @description 제너레이터 채움 — 진입점(onpageload)에서 순차 실행.
 * @param {String} boxId boxId
 * @returns {void}
 * @hidden N
 */
scwin.init_fillGen = function (boxId) {
    // 채우지 못한 자리를 모은다(동작은 계속 — 화면은 종전과 같다).
    const genSkip = [];
    let genCleared = 0;
    const genFills = [{ genId: "c_foreach_77", entity: "dlt_eduCompltAddList", countIds: [], cells: [{ childId: "option_78", fn: function (v, i) { return String(v("eduSchdlId")); } }, { childId: "__rc0", fn: function (v, i) { return "[" + String(v("eduCompltYear")) + "년] 『 " + String(v("disclsEduCrsNm")) + " 』 【 기간 : " + String(v("eduCompltDd")) + " 】 [인정시간 : " + String(v("eduAckTm")) + "시간]"; } }] }];
    const gf = genFills;
    for (let g = 0; g < gf.length; g++) {
        const f = gf[g];
        if (boxId && f.entity !== boxId) { continue; }
        const gen = $c.util.getComponent(f.genId);
        const ds = $c.util.getComponent(f.entity);
        if (!gen || !ds || !ds.getTotalRow) { genSkip.push({ gen: f.genId, box: f.entity, why: !gen ? 'no-generator' : 'no-box' }); continue; }
        const n = ds.getRowCount();
        if (!n) { genSkip.push({ gen: f.genId, box: f.entity, why: 'empty-box' }); continue; }
        // 멱등 — 이미 채워진 제너레이터는 건너뛴다(플래그 없이 컴포넌트 상태로 판단).
        //   단, 상자를 지정해 «다시 그리라» 고 부른 경우(데이터가 새로 담긴 때)는 비우고 다시 채운다.
        if (gen.getLength && gen.getLength() > 0) {
            if (!boxId) { continue; }
            const had = gen.getLength();
            while (gen.getLength() > 0) { gen.removeChild(); }
            genCleared += had;
        }
        let row = 0;
        const cell = function (col) { const v = ds.getCellData(row, col); return (v === undefined || v === null) ? '' : v; };
        for (let i = 0; i < n; i++) {
            row = i;
            gen.insertChild(i);
            for (let c = 0; c < f.cells.length; c++) {
                const ch = gen.getChild(i, f.cells[c].childId);
                if (!ch || !ch.setValue) { continue; }
                ch.setValue(f.cells[c].fn(cell, i));
            }
            for (let k = 0; k < f.countIds.length; k++) {
                const cn = gen.getChild(i, f.countIds[k]);
                if (cn && cn.setValue) { cn.setValue(String(i + 1)); }
            }
            // 행 조건 — 마지막 행에만 보이는 자리.
            if (f.rowConds) {
                for (let rc = 0; rc < f.rowConds.length; rc++) {
                    const rn = gen.getChild(i, f.rowConds[rc].childId);
                    if (!rn) { continue; }
                    const show = (f.rowConds[rc].kind === 'last') ? (i === n - 1) : true;
                    if (rn.setStyle) { rn.setStyle('display', show ? '' : 'none'); }
                }
            }
        }
    }
    if (genSkip.length) {
        // 우리 계측이 읽는 자리 — 화면 동작에는 영향이 없다.
        scwin.genFillSkipped = genSkip;
    }
    if (genCleared) { scwin.genFillCleared = (scwin.genFillCleared || 0) + genCleared; }
};

/**
 * @method
 * @name init
 * @description 화면 초기화 — 파라미터 수신·기본값·컴포넌트 초기 설정(onpageload 에서 순차 호출)
 * @returns {void}
 * @hidden N
 */
scwin.init = function () {

    scwin.PopupAutoResize();
};

/**
 * @method
 * @name init_loadList
 * @description 초기 목록 조회 — as-is 는 진입 자체가 조회였다
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.init_loadList = async function () {
    // 초기 목록 — as-is 는 진입 자체가 조회였다(근거: entry_edge). 진입점 합성이 이 단계를 잇는다.
    await scwin.tx_load_list();
};

/**
 * @method
 * @name init_recvParam
 * @description 화면 전환 파라미터 수신 — $c.data.getParameter() 를 dma_pageContext 에 담는다
 * @returns {void}
 * @hidden N
 */
scwin.init_recvParam = function () { dma_pageContext.setJSON($c.data.getParameter() ?? {}); };

///////// 3. 컴포넌트 이벤트 영역 /////////
/**
 * @method
 * @name grd_eduCompltList_oncellclick
 * @description grd_eduCompltList 셀 클릭 이벤트
 * @param {Number} rowIndex 행 인덱스
 * @param {Number} columnIndex 열 인덱스
 * @param {String} columnId 컬럼 id
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.grd_eduCompltList_oncellclick = async function (rowIndex, columnIndex, columnId) {
    try {
        const dl = $c.util.getComponent('dlt_eduCompltList');
        if (!dl) { /* TODO Stage2: [sdd] 행 동작 대상 목록 없음: dlt_eduCompltList */ return; }
        const r = dl.getRowJSON ? dl.getRowJSON(rowIndex) : null;
        if (!r) { return; }
        await scwin.delList(r["eduPartcId"], "", "", "", ""); return;
    } catch (e) {
        await $c.exception.handleError(e, { notify: 'none', context: 'grd_eduCompltList.oncellclick' });
    }
};

/**
 * @method
 * @name img_79_onclick
 * @description img_79 클릭 이벤트
 * @param {Object} e 이벤트 객체
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.img_79_onclick = async function(e){
    try {
        await scwin.addList('document.eduCompltListForm.addEduCrsNm.value','','','','')

    } catch (_ex) { await $c.exception.handleError(_ex, { context: 'jldfil25501.img_79_onclick' }); }
};

/**
 * @method
 * @name img_84_onclick
 * @description img_84 클릭 이벤트
 * @param {Object} e 이벤트 객체
 * @returns {void}
 * @hidden N
 */
scwin.img_84_onclick = function(e){
    try {
        scwin.close()

    } catch (_ex) { $c.exception.handleError(_ex, { context: 'jldfil25501.img_84_onclick' }); }
};

///////// 4. 서브미션 콜백 영역 /////////
/**
 * @method
 * @name tx_fn_delList
 * @description del List 서버 호출
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.tx_fn_delList = async function () {
    const sbmOptions = {
        id: "tx_fn_delList",
        method: "post",
        action: "/account/eduComplt.do",
        ref: "dma_delListReq",
        isProcessMsg: false
    };
    const res = await $c.sbm.executeDynamic(sbmOptions);
    if (res && res.skipped) { return res; }  // 중복 제출 skip
    if (!(res && res.responseJSON && res.responseJSON.success === true)) {
        const m = (res && res.responseJSON && res.responseJSON.message) || $c.sbm.getStatusMessage(res) || ('서버 응답 오류 (' + $c.sbm.getResultCode(res) + ')');
        await $c.win.alert(m);
    }
    return res;
};

/**
 * @method
 * @name tx_fn_addList
 * @description add List 서버 호출
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.tx_fn_addList = async function () {
    const sbmOptions = {
        id: "tx_fn_addList",
        method: "post",
        action: "/account/eduComplt.do",
        ref: "dma_addListReq",
        isProcessMsg: false
    };
    const res = await $c.sbm.executeDynamic(sbmOptions);
    if (res && res.skipped) { return res; }  // 중복 제출 skip
    if (!(res && res.responseJSON && res.responseJSON.success === true)) {
        const m = (res && res.responseJSON && res.responseJSON.message) || $c.sbm.getStatusMessage(res) || ('서버 응답 오류 (' + $c.sbm.getResultCode(res) + ')');
        await $c.win.alert(m);
    }
    return res;
};

/**
 * @method
 * @name tx_load_list
 * @description load list 서버 호출
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.tx_load_list = async function () {
    const sbmOptions = {
        id: "tx_load_list",
        method: "post",
        action: "/account/eduComplt.do?method=eduSchdlView&thisYear=",
        ref: "dma_loadListReq",
        target: "dlt_eduCompltAddList=body.content",
        isProcessMsg: false
    };
    const res = await $c.sbm.executeDynamic(sbmOptions);
    if (res && res.skipped) { return res; }  // 중복 제출 skip
    if (!(res && res.responseJSON && res.responseJSON.success === true)) {
        const m = (res && res.responseJSON && res.responseJSON.message) || $c.sbm.getStatusMessage(res) || ('서버 응답 오류 (' + $c.sbm.getResultCode(res) + ')');
        await $c.win.alert(m);
    }
    return res;
};

///////// 5. 일반/업무 함수 영역 /////////
/**
 * @method
 * @name grd_eduCompltList_fmt_column2
 * @description grd edu Complt List fmt column2 처리
 * @param {*} data 데이터
 * @param {*} formattedData 포맷된 값
 * @param {*} r r
 * @param {*} c c
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.grd_eduCompltList_fmt_column2 = async function (data, formattedData, r, c) {
    try {
        const dl = $c.util.getComponent("dlt_eduCompltList");
        const v = String(dl && dl.getCellData ? (dl.getCellData(r, "eduKindCd") ?? '') : '');
        if (v === '11') { return "공시책임자"; }
        if (v === '12') { return "공시담당자(정)"; }
        if (v === '13') { return "공시담당자(부)"; }
        if (v === '14') { return "공시대리인"; }
        if (v === '15') { return "공시담당보조자"; }
        return '';
    } catch (e) { await $c.exception.handleError(e, { notify: 'none', context: "grd_eduCompltList.column2" }); return String(data ?? ''); }
};

/**
 * @method
 * @name PopupAutoResize
 * @description Popup Auto Resize 처리
 * @returns {void}
 * @hidden N
 */
scwin.PopupAutoResize = function () {

    let thisX = parseInt(document.body.scrollWidth);
    let thisY = parseInt(document.body.scrollHeight);
    const maxThisX = screen.width - 50;
    const maxThisY = screen.height - 50;
    let marginY = 0;
    if (navigator.userAgent.indexOf("MSIE") > 0) {
        marginY = 70;
    } else {
        if (navigator.userAgent.indexOf("Firefox") > 0) {
            marginY = 50;
        } else {
            if (navigator.userAgent.indexOf("Opera") > 0) {
                marginY = 30;
            } else {
                if (navigator.userAgent.indexOf("Netscape") > 0) {
                    marginY = -2;
                }
            }
        }
    }
    if (thisX > maxThisX) {
        document.body.scroll = "yes";
        thisX = maxThisX;
    }
    if (thisY > maxThisY - marginY) {
        document.body.scroll = "yes";
        thisX += 19;
        thisY = maxThisY - marginY;
    }

};

/**
 * @method
 * @name close
 * @description close 처리
 * @returns {void}
 * @hidden N
 */
scwin.close = function () {
    (function () { const o = $c.win.getOpenerScope(); if (o) { $c.win.setPageFrameSrc($c.win.getFrame(o), null); } else { /* TODO Stage2: [sdd] 부모 창을 못 찾았다 — 새로고침하지 않는다(자기 화면을 다시 열면 무한 고리가 된다) */ } })();
    $c.win.closePopup();
};

/**
 * @method
 * @name delList
 * @description del List 처리
 * @param {String} eduPartcId eduPartcId
 * @param {String} isurCd isurCd
 * @param {String} chrgNm chrgNm
 * @param {String} chrgTpCd chrgTpCd
 * @param {String} disclsBzChrgAssgnDd disclsBzChrgAssgnDd
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.delList = async function (eduPartcId, isurCd, chrgNm, chrgTpCd, disclsBzChrgAssgnDd) {
    (document.eduCompltListForm || { elements: [] }).action = "/account/eduComplt.do";
    $c.util.getComponent('dma_delListReq').set('method', "eduCompltAct");
    $c.util.getComponent('dma_delListReq').set('actPlag', "delete");
    $c.util.getComponent('dma_delListReq').set('eduPartcId', eduPartcId);
    $c.util.getComponent('dma_delListReq').set('isurCd', isurCd);
    $c.util.getComponent('dma_delListReq').set('chrgNm', chrgNm);
    $c.util.getComponent('dma_delListReq').set('chrgTpCd', chrgTpCd);
    $c.util.getComponent('dma_delListReq').set('disclsBzChrgAssgnDd', disclsBzChrgAssgnDd);
    await scwin.tx_fn_delList();
};

/**
 * @method
 * @name addList
 * @description add List 처리
 * @param {String} eduSchdlId eduSchdlId
 * @param {String} isurCd isurCd
 * @param {String} chrgNm chrgNm
 * @param {String} chrgTpCd chrgTpCd
 * @param {String} disclsBzChrgAssgnDd disclsBzChrgAssgnDd
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.addList = async function (eduSchdlId, isurCd, chrgNm, chrgTpCd, disclsBzChrgAssgnDd) {
    if (eduSchdlId !== '') {
        (document.eduCompltListForm || { elements: [] }).action = "/account/eduComplt.do";
        $c.util.getComponent('dma_delListReq').set('method', "eduCompltAct");
        $c.util.getComponent('dma_delListReq').set('actPlag', "add");
        $c.util.getComponent('dma_delListReq').set('eduSchdlId', eduSchdlId);
        $c.util.getComponent('dma_delListReq').set('isurCd', isurCd);
        $c.util.getComponent('dma_delListReq').set('chrgNm', chrgNm);
        $c.util.getComponent('dma_delListReq').set('chrgTpCd', chrgTpCd);
        $c.util.getComponent('dma_delListReq').set('disclsBzChrgAssgnDd', disclsBzChrgAssgnDd);
        await scwin.tx_fn_addList();
    } else {
        await $c.win.alert("추가할 교육과정을 선택해주세요.");
    }
};
